        if post_residual >= next_item_size {
            // Reward bins that create a perfect or near-perfect fit for the next item.
            score -= (100.0 - (post_residual - next_item_size) as f64) * 0.5;
        } else {
            // Penalize bins that cannot fit the next item if better alternatives exist.
            score += 20.0;
        }
    }

    // 3. Last Chance Logic: If this is the only bin that fits, we must take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 4. New Bin Thresholding: Discourage opening new bins unless the current residual is very poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of existing bins is already quite tight,
        // or if we are early in the stream (exploration phase).
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 + (mean_residual * 0.5) + (progress * 20.0);
    }

    // 5. Harmonic Class Preference: Favor bins that leave larger, more flexible residuals.
    // We prefer residuals that align with common item size clusters (e.g., multiples of 20).
    let harmonic_alignment = (post_residual % 20) as f64;
    score += harmonic_alignment * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is too small to fit any likely future item (e.g., < 10),
    // it creates "stranded" space. Penalize these gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item can fit perfectly or near-perfectly into the remaining space,
    // reward this bin to keep it "active" for the next step.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_diff = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 / (fit_diff + 1.0));
    }

    // 3. Open Bins Pressure: Penalize opening a new bin if we have many bins already open.
    // This forces the algorithm to consolidate items into existing bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += (open_bins_count as f64) * 5.0;

        // If there are other bins that could fit this item, penalize opening a new one heavily.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Tight Fit Reward: Heavily favor bins that become very full (Best-Fit principle).
    // This minimizes the number of bins by maximizing density.
    score -= (bin_capacity - post_residual) as f64 * 0.5;

    // 5. Global Balance: If the current bin's residual is much higher than the mean residual,
    // it's likely a "wasteful" bin. Penalize it to push items toward tighter bins.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Encourage Best-Fit: penalize larger post-residuals (wasted space)
    // We add a quadratic penalty to discourage leaving large gaps.
    score += (post_residual as f64).powi(2) * 0.05;

    // 2. Lookahead Synergy: If the next item fits into the post_residual,
    // we reward this bin heavily to encourage tight packing of pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
        // Further reward if it creates a perfect fit (zero waste)
        if post_residual == next_item_size {
            score -= 50.0;
        }
    }

    // 3. Mean Residual Balancing: Avoid bins that deviate significantly from the 
    // global mean residual of open bins to keep bin states synchronized.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 4. Scarcity/New Bin Logic:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless no other bins can fit the item (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0; // Strong penalty against opening a new bin prematurely
        } else {
            score -= 20.0;  // Incentive to open if absolutely necessary
        }
    }

    // 5. Progression scaling: As we reach the end of the sequence, 
    // prioritize closing bins (minimizing residuals) over lookahead utility.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
