pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation heavily early on, but allow more flexibility as we near completion
    let new_bin_penalty = if is_new_bin {
        50.0 * (1.0 - progress).powf(0.5) + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Calculate base score: favor smaller post_residuals (Best Fit)
    // Non-linear coupling: penalize very small residuals that are unlikely to fit future items
    // If post_residual is < 10, it is likely "wasted" space.
    let waste_penalty = if post_residual < 10 && post_residual > 0 {
        (10.0 - post_residual as f64) * 5.0
    } else {
        0.0
    };

    // Lookahead logic: if the next item fits into the current post_residual, reward this bin
    let lookahead_reward = if next_item_size > 0 && post_residual >= next_item_size {
        -25.0 * (1.0 - (post_residual as f64 / bin_capacity as f64))
    } else {
        0.0
    };

    // Interaction with mean_residual: avoid bins that deviate significantly from the average
    // state of the packing, which helps keep bin filling levels consistent.
    let consistency_penalty = (post_residual as f64 - mean_residual).powi(2) * 0.01;

    // Final score: minimize this value
    let mut score = post_residual as f64 + waste_penalty + new_bin_penalty + lookahead_reward + consistency_penalty;

    // If this is the last chance to fit the item in an existing bin, reduce the penalty for poor fits
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
