        // (i.e., keep bins "open" for larger items later).
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // 4. Scarcity avoidance: If this is the last chance to fit an item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
