    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // 2. Harmonic/Modulo logic: If post_residual is small, it's often better, 
    //    but if it's very small (e.g., 1-5), it might be "unusable" space.
    //    We reward "perfect fits" (post_residual == 0) heavily.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 5 {
        score += 20.0; // Penalize "near-miss" dead space
    }

    // 3. Lookahead integration: If the next item fits into the current post_residual, 
    //    prioritize this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further refine: if next item fits perfectly, reward even more
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // 4. Bin count management: Penalize opening new bins unless necessary.
    //    If bin_residual == bin_capacity, this is a new bin.
    if bin_residual == bin_capacity {
        score += 60.0; 
        // If we have many open bins, opening another is costly.
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Mean residual balancing:
    //    If this bin's post_residual is significantly worse than the average, penalize it.
    if (post_residual as f64) > mean_residual {
        score += 10.0;
    }

    // 6. Last chance logic: If this is the only bin that fits, we must take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 7. Progression factor: As we approach the end of the stream, 
    //    be more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let post_residual_f = post_residual as f64;
    let bin_capacity_f = bin_capacity as f64;

    // Core logic: Increased power to penalize large remainders more aggressively (First-Fit Decreasing refinement).
    let mut score = post_residual_f.powf(1.85);

    if !is_new_bin {
        // Penalty for fragmentation: Scaled by open_bins_count to suppress fragmentation in active bins.
        score += (post_residual_f / bin_capacity_f) * 44.0 * (1.0 + progress.powf(0.98));

        // Refined Lookahead: Focus on minimizing "dead zones" that cannot fit next_item_size.
        if next_item_size > 0 {
            if post_residual > 0 && post_residual < next_item_size {
                // Exponentially penalize unusable gaps that create stranded capacity.
                score += ((next_item_size - post_residual) as f64).powf(2.45) * 20.2;
            } else if post_residual >= next_item_size {
                // Reward bins that remain "ready" for the next item, scaling reward with progress.
                score -= (next_item_size as f64) * (5.2 + progress * 4.5);
            }
        }

        // Entropy control: Increased penalty for deviating from mean_residual to force uniform filling.
        score += (post_residual_f - mean_residual).abs() * 1.55;
    } else {
        // New bin decision matrix:
        if fitting_bins_count > 0 {
            // Increased resistance to opening new bins when existing ones have potential.
            let density_pressure = (open_bins_count as f64).powf(1.12) * 25.0;
            let fragmentation_relief = (1.0 - (mean_residual / bin_capacity_f)) * 110.0;
            score += 185.0 + (mean_residual * 1.65) + density_pressure - fragmentation_relief;
        } else {
            // Mandatory bin opening reward.
            score -= 300.0;
        }
    }

    // Late-stage compaction: Aggressive clearing of near-full bins.
    if progress > 0.55 {
        let filled_amount = (bin_capacity - bin_residual) as f64;
        // Reward bins that reach high density to clear them from the active search set.
        score -= filled_amount.powf(1.75) * 4.8;

        // Dynamic barrier: Increasing cost to open new bins as we approach exhaustion.
        if is_new_bin {
            score += 135.0 * (progress - 0.55).powf(1.3) / 0.45;
        }
    }

    // Secondary heuristic: Penalize bins that are significantly emptier than the global mean to avoid stragglers.
    if !is_new_bin && post_residual_f > mean_residual * 1.6 {
        score += (post_residual_f - mean_residual) * 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

