    // If post_residual is in the "danger zone" (1..9), we inflate the score significantly.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 15.0;
    }

    // 2. Lookahead Synergy: If the next item can fit perfectly or near-perfectly into the current post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap_after_next = (post_residual - next_item_size) as f64;
        if gap_after_next == 0.0 {
            score -= 40.0; // Perfect fit bonus
        } else if gap_after_next >= 10.0 {
            score -= 10.0; // Good slack bonus
        }
    }

    // 3. Open Bins Pressure: If we have many open bins, penalize opening a new one (bin_residual == bin_capacity).
    // If fitting_bins_count is 0, we are forced to open a new one, so we neutralize the penalty.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += (open_bins_count as f64) * 25.0;
    }

    // 4. Mean Residual Balancing: Prefer bins closer to the global average residual to keep compaction uniform.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.5;

    // 5. Progression weighting: As the stream nears the end, be more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += post_residual as f64 * 2.0; 
    }

    score
}

