    let is_new_bin = bin_residual == bin_capacity;
    let post_residual_f = post_residual as f64;
    let bin_capacity_f = bin_capacity as f64;

    // Core logic: Increased exponent (1.95) to prioritize tighter fits more aggressively.
    let mut score = post_residual_f.powf(1.95);

    if !is_new_bin {
        // Fragmentation: Scale by open_bins_count and progress to maintain tight packing.
        score += (post_residual_f / bin_capacity_f) * 50.0 * (1.0 + progress.powf(0.9));

        // Lookahead: Tighten the dead-zone penalty to avoid creating small, unusable gaps.
        if next_item_size > 0 {
            if post_residual > 0 && post_residual < next_item_size {
                score += ((next_item_size - post_residual) as f64).powf(2.65) * 24.0;
            } else if post_residual >= next_item_size {
                // Reward bins that remain "ready" for the next item.
                score -= (next_item_size as f64) * (6.0 + progress * 6.0);
            }
        }

        // Entropy control: Penalty for variance from mean_residual.
        score += (post_residual_f - mean_residual).abs() * 1.85;

        // Local scarcity: Stronger reward for the last-resort bin.
        if fitting_bins_count == 1 {
            score -= 105.0;
        }
    } else {
        // New bin decision matrix:
        if fitting_bins_count > 0 {
            // Increased resistance to opening new bins.
            let density_pressure = (open_bins_count as f64).powf(1.18) * 35.0;
            let fragmentation_relief = (1.0 - (mean_residual / bin_capacity_f)) * 130.0;
            score += 210.0 + (mean_residual * 1.85) + density_pressure - fragmentation_relief;
        } else {
            // Mandatory bin opening reward.
            score -= 750.0;
        }
    }

    // Late-stage compaction: Aggressive clearing of near-full bins.
    if progress > 0.45 {
        let filled_amount = (bin_capacity - bin_residual) as f64;
        // Reward bins that reach high density.
        score -= filled_amount.powf(1.85) * 5.8;

        // Dynamic barrier: Sharper cost to open new bins as we approach the end.
        if is_new_bin {
            score += 180.0 * (progress - 0.45).powf(1.35);
        }
    }

    // Secondary heuristic: Penalize bins that are significantly emptier than the global mean.
    // Tightened the threshold from 1.5 to 1.3 to keep bins more uniform.
    if !is_new_bin && post_residual_f > mean_residual * 1.3 {
        score += (post_residual_f - mean_residual) * 3.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We prefer smaller post_residuals (Best Fit logic)
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' (small residuals that are hard to fill)
    // If post_residual is between 1 and 9, it is highly likely to become unusable waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: If a future item exists, evaluate compatibility
    if next_item_size > 0 {
        let fit_next = post_residual >= next_item_size;
        if fit_next {
            // Reward bins that can accommodate the next item perfectly
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize bins that block the next item from fitting
            score += 10.0 * (1.0 - progress);
        }
    }

    // New Bin Management: Only open a new bin if the current fit is extremely poor
    // or if we are nearing the end of the stream and need to consolidate.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if others are available
            score += 45.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Baseline cost for mandatory new bin
            score = 20.0;
        }
    }

    // Global state optimization: Balance the load across bins
    // If the current bin's residual is significantly larger than the mean, 
    // it's a good candidate to keep open.
    if !is_new_bin {
        let residual_diff = bin_residual as f64 - mean_residual;
        score -= residual_diff * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
