        // Entropy control: Keep residuals near the mean to prevent extreme bin variances.
        // Sensitivity increased to force convergence toward a uniform mean residual.
        score += (post_residual_f - mean_residual).abs() * 1.8;

        // Local scarcity: Force-taking the only available option.
        if fitting_bins_count == 1 {
