    // Penalty for creating 'dead space' (bins left with very small, unusable capacity).
    // If post_residual is small (e.g., < 10), it's often better to save that space 
    // for future items, unless it's the perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - post_res_f / 10.0);
