        }
    }

    // Stream progression adjustment: As we approach the end of the stream, 
    // we become more aggressive in forcing tight fits to close existing bins.
    let exhaustion_factor = progress.powi(2) * 20.0;
    score -= exhaustion_factor * (1.0 - post_res_f / bin_capacity as f64);

    // If this is a new bin, penalize it based on how many bins are already open 
    // and whether existing bins could have accommodated the item.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high.
        score += 45.0;

        // If we have fitting bins, opening a new bin is very undesirable.
