    let is_new_bin = bin_residual == bin_capacity;
    let post_residual_f = post_residual as f64;
    let bin_capacity_f = bin_capacity as f64;

    // Core objective: Minimize post_residual. 
    // We adjust exponent to 2.1 to penalize larger residuals more harshly than the parent.
    let mut score = post_residual_f.powf(2.1);

    if !is_new_bin {
        // Fragmentation pressure: Refined to scale with current bin count to keep load balanced.
        score += (post_residual_f / bin_capacity_f) * 55.0 * (1.0 + progress.powf(0.5));

        // Refined Lookahead:
        // Use a tighter penalty for "dead zones" to preserve space for next_item_size.
        if next_item_size > 0 {
            if post_residual > 0 && post_residual < next_item_size {
                score += ((next_item_size - post_residual) as f64).powf(2.8) * 25.0;
            } else if post_residual >= next_item_size {
                // Reward bins that maintain utility, but dampen based on current mean to avoid over-filling.
                score -= (next_item_size as f64) * (6.2 + progress * 4.0);
            }
        }

        // Entropy control: Increased weight to force residuals to converge toward the mean.
        score += (post_residual_f - mean_residual).abs().powf(1.2) * 2.2;

        // Local scarcity: Force-take for single-fit bins.
        if fitting_bins_count == 1 {
            score -= 120.0;
        }
    } else {
        // New bin decision matrix:
        if fitting_bins_count > 0 {
            // Refined cost to open new bin: 
            // Penalize based on how well the average bin is currently performing.
            let density_pressure = (open_bins_count as f64).powf(1.15) * 30.0;
            let fragmentation_relief = (1.0 - (mean_residual / bin_capacity_f)).powf(0.8) * 115.0;
            score += 210.0 + (mean_residual * 2.1) + density_pressure - fragmentation_relief;
        } else {
            score -= 600.0;
        }
    }

    // Late-stage compaction: 
    // Shifted from 0.55 to 0.45 to start consolidation earlier in the stream.
    if progress > 0.45 {
        let filled_amount = (bin_capacity - bin_residual) as f64;
        score -= filled_amount.powf(1.85) * 5.2;

        if is_new_bin {
            // Stricter barrier for new bins as the stream nears exhaustion.
            score += 180.0 * (progress - 0.45).powf(1.5);
        }
    }

    // Secondary outlier constraint: 
    // Increased penalty for bins significantly emptier than the average.
    if !is_new_bin && post_residual_f > mean_residual * 1.4 {
        score += (post_residual_f - mean_residual) * 3.5;
    }

    score
}

