    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize small remaining gaps that are hard to fill (the "fragmentation" trap).
    // Residuals between 1 and 9 are notoriously difficult to fill given the input range (10-100).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, drastically reduce the score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Reward tighter fits for the lookahead item.
        score -= (post_residual - next_item_size) as f64 * 0.2;
