        score += (1.0 - (step_index as f64 / total_items as f64)) * 20.0;
    }

    // 4. Harmonic Alignment: Favor filling bins to near-capacity (modulo arithmetic logic).
    // Specifically, prioritize bins that, if filled, leave a residual that is a multiple of 10 or 25,
