    let remainder = post_residual % 25;
    if remainder == 0 {
        score -= 10.0;
    } else if remainder > 20 {
        score += 5.0;
    }

    // 5. Mean Residual Balancing: Avoid creating bins that are significantly more empty than the average.
    if (post_residual as f64) > mean_residual * 1.2 {
        score += 15.0;
    }

    // 6. Last Resort Protection: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

