    let is_new_bin = bin_residual == bin_capacity;
    let post_residual_f = post_residual as f64;
    let capacity_f = bin_capacity as f64;

    // Refined core objective: Use a steeper exponential penalty for gaps to force Best-Fit,
    // but normalize against capacity to prevent scaling bias on large bins.
    let mut score = (post_residual_f / capacity_f).powf(2.1) * 150.0;

    if !is_new_bin {
        // Fragmentation pressure: Penalize bins that leave gaps smaller than the average item.
        // The weight now scales quadratically with the ratio of the gap to the bin capacity.
        score += (post_residual_f / capacity_f) * 60.0 * (1.0 + progress.powf(0.5));

        // Enhanced Lookahead:
        // Penalize "dead zones" more aggressively if they are smaller than the next incoming item.
        if next_item_size > 0 {
            if post_residual > 0 && post_residual < next_item_size {
                score += ((next_item_size - post_residual) as f64).powf(2.8) * 25.0;
            } else if post_residual >= next_item_size {
                // Reward bins that maintain enough space to accommodate the next item comfortably.
                score -= (next_item_size as f64) * (6.5 + progress * 8.0);
            }
        }

        // Entropy control: Minimize variance from the mean to encourage uniform packing.
        score += (post_residual_f - mean_residual).abs() * 2.2;

        // Local scarcity: Force usage of existing bins if they are the only option.
        if fitting_bins_count == 1 {
            score -= 120.0;
        }
    } else {
        // New bin decision matrix:
        if fitting_bins_count > 0 {
            // Threshold logic: Only open a new bin if the existing fragmentation is high.
            // density_pressure acts as a deterrent for opening bins too quickly.
            let density_pressure = (open_bins_count as f64).powf(1.2) * 30.0;
            let fragmentation_relief = (1.0 - (mean_residual / capacity_f)) * 130.0;
            score += 220.0 + (mean_residual * 2.1) + density_pressure - fragmentation_relief;
        } else {
            // Absolute necessity: Forced new bin opening.
            score -= 800.0;
        }
    }

    // Late-stage compaction: Aggressively finalize near-full bins to close them out.
    if progress > 0.60 {
        let filled_amount = (bin_capacity - bin_residual) as f64;
        score -= filled_amount.powf(1.85) * 5.5;

        // Dynamic barrier: Increase the cost to open new bins as the stream nears completion.
        if is_new_bin {
            score += 180.0 * (progress - 0.60).powf(1.5);
        }
    }

    // Outlier constraint: Penalize bins that are significantly emptier than the current mean.
    if !is_new_bin && post_residual_f > mean_residual * 1.5 {
        score += (post_residual_f - mean_residual) * 4.0;
    }

    score
}

