    // Objective: Minimize post_residual, but heavily penalize small gaps (1..10) 
    // that become "dead space". Reward filling bins to near-zero residuals.

    let mut score = post_residual as f64;

    // Penalty for creating "unusable" small gaps (1..10).
    // If post_residual is small but > 0, it's likely dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 / (post_residual as f64).sqrt();
    }

    // Lookahead logic: If a future item exists, prioritize bins that can fit it.
    // If next_item_size is large, we want to preserve larger residuals.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 20.0;
        }
    }

    // Pressure against opening too many bins.
    // As open_bins_count increases, increase the penalty for opening a new bin (where bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // If this is the last chance for the current item (fitting_bins_count == 1),
    // reduce the penalty to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Reward bins that stay close to the current mean_residual to keep distribution uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

