    // Residuals between 1 and 9 are often unusable; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead matching: reward bins that leave exactly enough space for the next item.
    // If post_residual is close to next_item_size, it's a high-quality placement.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;

        // Reward if the next item fits perfectly or near-perfectly
        if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // 3. Global Bin Management:
    // If this is a new bin (bin_residual == bin_capacity), penalize opening it
    // unless all other bins are poor fits.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Mean Residual Balancing:
    // Avoid creating bins that deviate significantly from the current average density.
    let density_deviation = (post_residual as f64 - mean_residual).abs();
    score += density_deviation * 0.5;

    // 5. Urgency:
    // If this is the last bin that can fit the item, prioritize it to keep bin count low.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Progression scaling:
    // As we approach the end of the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
