    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin heavily unless the current open bins are very full
    if is_new_bin {
        if open_bins_count == 0 {
            return 0.0;
        }
        // Only open a new bin if the average residual of current bins is very low (fragmentation)
        score = mean_residual * 2.5;
    } else {
        // 2. Best-Fit logic: prioritize small post_residuals
        // 3. Lookahead bonus: if the next item fits in the post_residual, prioritize this bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
