        // 4. Dead-space penalty: If post_residual is too small to fit any common item (e.g., < 10),
        // it's often better to leave it larger or pick a different bin.
        if post_residual > 0 && post_residual < 12 {
            score += 25.0;
        }

        // 5. Global state normalization: If we have many open bins, be more aggressive
        // in filling existing ones (Best-Fit) to avoid opening more.
        if open_bins_count > 5 {
            score -= (open_bins_count as f64) * 0.5;
        }
    }

    // 6. Time horizon: As we approach the end of the stream, prioritize filling 
    // remaining space over saving it for potential future items.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

