    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit approach)
    let mut score = post;

    // Penalty for creating "dead space" that is likely too small for future items.
    // As progress increases, we become more aggressive about conserving space.
    let dead_space_penalty = if post < 10.0 {
        (10.0 - post) * 5.0 * (1.0 + progress)
    } else {
        0.0
