    score += dead_space_penalty;

    // Lookahead coupling: if the next item is large, prioritize bins that keep 
    // enough space to accommodate it.
    if next_item_size > 0 {
        if post < (next_item_size as f64) {
            score += (next_item_size as f64 - post) * 2.5;
        }
