    // Heuristic for new bin creation:
    // If the bin is new, penalize based on how much space we waste relative to the mean.
    // We only want to open a new bin if the current fit is significantly worse than
    // the average utilization of existing bins.
    if bin_residual == bin_capacity {
        score += mean_residual * 0.8;
        // As we reach the end of the stream, discourage opening new bins.
        score += progress * 50.0;
    }

    // Reward bins that have high utilization (low residual)
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;

