pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let post_residual_f = post_residual as f64;

    // Core objective: Minimize post_residual with a high-order penalty to prioritize Best-Fit.
    // Shift exponent to 1.95 to sharpen the distinction between tight fits and loose fits.
    let mut score = post_residual_f.powf(1.95);

    if !is_new_bin {
        // Fragmentation pressure: Penalize bins that leave awkward gaps.
        // Scaling factor increased slightly to prioritize compaction over early-stream exploration.
        score += (post_residual_f / bin_capacity as f64) * 48.0 * (1.0 + progress.powf(0.9));

        // Advanced Lookahead:
        // Use a non-linear penalty for "dead zones" (gaps smaller than the next item).
        if next_item_size > 0 {
            if post_residual > 0 && post_residual < next_item_size {
                score += ((next_item_size - post_residual) as f64).powf(2.6) * 22.0;
            } else if post_residual >= next_item_size {
                // Reward bins that maintain "utility" for the immediate future.
                score -= (next_item_size as f64) * (6.0 + progress * 6.0);
            }
        }

        // Entropy control: Keep residuals near the mean to prevent extreme bin variances.
        score += (post_residual_f - mean_residual).abs() * 1.8;

        // Local scarcity: Stronger incentive to use the only available fitting bin.
        if fitting_bins_count == 1 {
            score -= 110.0;
        }
    } else {
        // New bin decision matrix:
        if fitting_bins_count > 0 {
            // Calculate a "cost" to open a new bin based on existing fragmentation.
            let density_pressure = (open_bins_count as f64).powf(1.15) * 28.0;
            let fragmentation_relief = (1.0 - (mean_residual / bin_capacity as f64)) * 120.0;
            score += 210.0 + (mean_residual * 2.0) + density_pressure - fragmentation_relief;
        } else {
            // If no existing bin can fit, force new bin opening with a strong negative bias.
            score -= 650.0;
        }
    }

    // Late-stage compaction: Aggressively finalize near-full bins.
    if progress > 0.50 {
        let filled_amount = (bin_capacity - bin_residual) as f64;
        // Reward high-density completion to reduce active open_bins_count.
        score -= filled_amount.powf(1.8) * 5.5;

        // Dynamic barrier: Increasing cost to open new bins as we approach stream exhaustion.
        if is_new_bin {
            score += 180.0 * (progress - 0.50).powf(1.4);
        }
    }

    // Secondary outlier constraint: Penalize "too empty" bins relative to the current mean.
    // Tightened the threshold to 1.5x mean to force tighter packing earlier.
    if !is_new_bin && post_residual_f > mean_residual * 1.5 {
        score += (post_residual_f - mean_residual) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize mid-range slivers (5-15)
    // which are difficult to fill later.
    if post_residual > 5 && post_residual < 15 {
        score += 25.0;
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // prioritize this bin to maximize bin density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Global State: If we are nearing the end of the stream, prioritize packing
    // tightly into existing bins to avoid opening new ones.
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 2.0;
    }

    // 4. New Bin Logic: If we are considering a brand new bin (residual == capacity),
    // add a high threshold cost. Only pick it if existing bins are all "bad" fits.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless we have very few options
        score += 60.0 + (mean_residual * 0.5);
    } else {
        // Reward bins that keep the mean residual of the system balanced
        if (post_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // 5. Scarcity Constraint: If this is the last bin that can fit the item, 
    // it is inherently more valuable than a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let post_residual_f = post_residual as f64;
    let bin_residual_f = bin_residual as f64;

    // Core objective: Minimize post_residual with a cubic-like penalty to drive near-perfect fits.
    // Increased exponent to 2.1 to penalize larger gaps more severely than the parent.
    let mut score = post_residual_f.powf(2.1);

    if !is_new_bin {
        // Fragmentation pressure: Refined to scale with current bin depth.
        score += (post_residual_f / bin_capacity as f64) * 55.0 * (1.0 + progress.sqrt());

        // Advanced Lookahead:
        // Use a tighter penalty for "dead zones" (gaps smaller than the next item) 
        // and a more aggressive reward for "utility" (maintaining space for next item).
        if next_item_size > 0 {
            if post_residual > 0 && post_residual < next_item_size {
                score += ((next_item_size - post_residual) as f64).powf(2.65) * 28.0;
            } else if post_residual >= next_item_size {
                score -= (next_item_size as f64) * (7.2 + progress * 6.0);
            }
        }

        // Entropy control: Increased weighting to force tight variance around the mean.
        score += (post_residual_f - mean_residual).abs() * 2.2;

        // Local scarcity: Force-fit if this is the only viable bin.
        if fitting_bins_count == 1 {
            score -= 110.0;
        }
    } else {
        // New bin decision matrix:
        if fitting_bins_count > 0 {
            // Calculate a "cost" to open a new bin. 
            // We penalize opening new bins when existing bins are already near-empty (low density_pressure).
            let density_pressure = (open_bins_count as f64).powf(1.15) * 35.0;
            let fragmentation_relief = (1.0 - (mean_residual / bin_capacity as f64).powf(0.8)) * 120.0;
            score += 210.0 + (mean_residual * 2.1) + density_pressure - fragmentation_relief;
        } else {
            score -= 600.0;
        }
    }

    // Late-stage compaction: Aggressively finalize near-full bins.
    if progress > 0.5 {
        let filled_amount = (bin_capacity - bin_residual) as f64;
        // Reward high-density completion to reduce active open_bins_count.
        score -= filled_amount.powf(1.85) * 6.2;

        // Dynamic barrier: Increasing cost to open new bins as we approach stream exhaustion.
        if is_new_bin {
            score += 180.0 * (progress - 0.5).powf(1.5);
        }
    }

    // Secondary outlier constraint: Penalize "too empty" bins relative to the current mean.
    // Tightened the threshold for outlier penalization to 1.4x mean.
    if !is_new_bin && post_residual_f > mean_residual * 1.4 {
        score += (post_residual_f - mean_residual) * 3.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post;

    // Penalty for creating "slivers" (very small residuals that are hard to fill)
    // We penalize residuals between 1 and 9 significantly.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead coupling: If a subsequent item is large, favor larger residuals now.
    // If next_item_size is large, we want to avoid tight fits that block future placement.
    if next_item_size > 50 {
        score += (next_item_size as f64 - post) * 0.5;
    }

    // Dynamic Thresholding: As the stream nears completion, become more aggressive 
    // about filling existing bins to avoid leaving stragglers.
    let fill_urgency = (1.0 - progress).powf(2.0) * 10.0;
    score -= (bin_capacity as f64 - post) * fill_urgency;

    // Multi-bin interaction: Penalize opening new bins unless the current bin
    // fit is objectively poor compared to the mean of other bins.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Only pick this if the average residual of existing bins is already very low,
        // suggesting that new items won't fit anywhere well.
        score += mean_residual * 1.5;
        score += (open_bins_count as f64) * 2.0;
    } else {
        // Reward bins that bring the residual closer to the global mean,
        // promoting uniform packing density.
        score += (post - mean_residual).abs() * 0.5;
    }

    // Critical constraint: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let post_residual_f = post_residual as f64;

    // Core objective: Minimize post_residual. Exponent 1.82 balances fill-density vs distribution.
    let mut score = post_residual_f.powf(1.82);

    if !is_new_bin {
        // Fragmentation pressure: Penalize bins that leave awkward gaps.
        score += (post_residual_f / bin_capacity as f64) * 42.0 * (1.0 + progress.sqrt());

        // Advanced Lookahead: 
        // Penalize dead zones (gaps smaller than next item) more sharply to preserve fitting capacity.
        if next_item_size > 0 {
            if post_residual > 0 && post_residual < next_item_size {
                score += ((next_item_size - post_residual) as f64).powf(2.4) * 22.0;
            } else if post_residual >= next_item_size {
                // Reward bins that maintain "utility" for the next item, adjusted by progress.
                score -= (next_item_size as f64) * (6.0 + progress * 6.0);
            }
        }

        // Entropy control: Keep residuals near the mean, but allow more variance early on.
        score += (post_residual_f - mean_residual).abs() * (1.2 + progress);

        // Local scarcity: If this is the only bin that fits, prioritize it strongly.
        if fitting_bins_count == 1 {
            score -= 110.0;
        }
    } else {
        // New bin decision matrix:
        if fitting_bins_count > 0 {
            // Calculate "cost" to open a new bin.
            // Increased sensitivity to open_bins_count to prevent runaway bin creation.
            let density_pressure = (open_bins_count as f64).powf(1.05) * 28.0;
            let fragmentation_relief = (1.0 - (mean_residual / bin_capacity as f64)) * 95.0;
            score += 195.0 + (mean_residual * 1.5) + density_pressure - fragmentation_relief;
        } else {
            // Mandatory bin opening.
            score -= 600.0;
        }
    }

    // Late-stage compaction: Aggressively finalize near-full bins.
    if progress > 0.5 {
        let filled_amount = (bin_capacity - bin_residual) as f64;
        // Reward high-density completion.
        score -= filled_amount.powf(1.65) * 5.2;

        // Dynamic barrier: Sharper cost to open new bins as we approach exhaustion.
        if is_new_bin {
            score += 150.0 * (progress - 0.5).powf(1.2);
        }
    }

    // Secondary outlier constraint: Penalize "too empty" bins relative to the current mean.
    // Adjusted threshold to be slightly more tolerant of large residuals if bin count is low.
    if !is_new_bin && post_residual_f > mean_residual * 1.8 {
        score += (post_residual_f - mean_residual) * 3.0;
    }

    score
}
